#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}


# ──────────────────────────────────────────────────────────────────────────
# STAGES — author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# Connects WhatsApp to the tracker webhook at https://vikrampareddy.com/api/whatsapp.
# Secrets stay in this process's memory: nothing is written to disk or printed.
# Each secret goes to the clipboard only for the moment you paste it.

TOTAL_STAGES=9

REPO="vikram-gsu/vrblog"
SITE="https://vikrampareddy.com"
WEBHOOK="$SITE/api/whatsapp"
GRAPH="https://graph.facebook.com/v23.0"
VERCEL_ENV_URL="https://vercel.com/vikrams-projects-77a25b04/vrblog/settings/environment-variables"
VERCEL_DEPLOYS_URL="https://vercel.com/vikrams-projects-77a25b04/vrblog/deployments"

# to_clipboard NAME VALUE — put a value on the clipboard without echoing it.
to_clipboard() {
  if command -v pbcopy >/dev/null 2>&1; then
    printf '%s' "$2" | pbcopy
    printf '  %s✓ copied%s %s to the clipboard\n' "$GREEN" "$RESET" "$1"
  else
    warn "no pbcopy; paste $1 from where you copied it"
  fi
}

clear_clipboard() { command -v pbcopy >/dev/null 2>&1 && printf '' | pbcopy || true; }
trap clear_clipboard EXIT

# graph METHOD PATH — call the Graph API with the token sent on stdin, so it never shows in `ps`.
graph() {
  printf 'Authorization: Bearer %s\n' "$WHATSAPP_ACCESS_TOKEN" |
    curl -s -X "$1" -H @- "$GRAPH/$2"
}

banner "WhatsApp → tracker setup"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "GitHub token the bot commits with"
say "The webhook adds lines to content/tracker/log.yaml via the GitHub API."
say "Make a token that can only touch that one repo."
open_url "https://github.com/settings/personal-access-tokens/new"
step "Make sure you're signed in as ${BOLD}vikram-gsu${RESET} (top-right avatar)."
step "Token name: vrblog-tracker-bot · Expiration: 90 days (or longer)."
step "Resource owner: vikram-gsu · Repository access: Only select repositories → vrblog."
step "Permissions → Repository → Contents: Read and write. Leave the rest."
step "Generate token, then copy it."
while :; do
  ask_secret GITHUB_TOKEN "Paste the GitHub token:"
  code=$(printf 'Authorization: Bearer %s\n' "$GITHUB_TOKEN" |
    curl -s -o /dev/null -w '%{http_code}' -H @- "https://api.github.com/repos/$REPO/contents/content/tracker/log.yaml" || true)
  if [[ "$code" == "200" ]]; then printf '  %s✓ token can read %s%s\n' "$GREEN" "$REPO" "$RESET"; break; fi
  warn "GitHub answered $code for that token. Check the owner/repo, then paste again."
done
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Meta developer app with WhatsApp"
say "Meta's WhatsApp Cloud API is free and comes with a test number."
open_url "https://developers.facebook.com/apps/creation/"
step "Sign in (register as a developer if asked; it's free)."
step "Create app → use case ${BOLD}Connect with customers through WhatsApp${RESET}."
step "Name it e.g. 'Tracker bot'; pick or create a business portfolio when asked."
step "Finish creation. You land on the app dashboard."
note "Meta reshuffles this flow often; if labels differ, look for 'WhatsApp' as the product/use case."
pause "Press Enter once the app exists"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Test number and your phone"
step "In the app: WhatsApp → API Setup (newer dashboards: Use cases → Customize → API Setup)."
step "Under 'From' there's a free test number. Copy the ${BOLD}Phone number ID${RESET} shown under it."
ask WHATSAPP_PHONE_NUMBER_ID "Phone number ID:"
step "Also copy the ${BOLD}WhatsApp Business Account ID${RESET} shown on the same page."
ask WABA_ID "WhatsApp Business Account ID:"
step "Under 'To' → Manage phone number list → add your own number and enter the code WhatsApp sends."
say "Your number, digits only with country code (e.g. 14045551234):"
ask WHATSAPP_ALLOWED_FROM "Your number:"
WHATSAPP_ALLOWED_FROM="${WHATSAPP_ALLOWED_FROM//[^0-9]/}"
note "Only messages from $WHATSAPP_ALLOWED_FROM will be logged; everything else is ignored."
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "App secret (to check Meta's signatures)"
step "App dashboard → App settings → Basic."
step "Next to 'App secret' click Show (re-enter your Facebook password), then copy."
ask_secret WHATSAPP_APP_SECRET "Paste the app secret:"
if [[ ! "$WHATSAPP_APP_SECRET" =~ ^[0-9a-f]{32}$ ]]; then
  warn "App secrets are usually 32 hex characters; double-check you copied the whole thing."
  confirm "Keep it anyway?" || ask_secret WHATSAPP_APP_SECRET "Paste the app secret again:"
fi
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Permanent access token (system user)"
say "The token on the API Setup page expires in 24 hours. A system user token doesn't."
open_url "https://business.facebook.com/settings/system-users"
step "Business settings → Users → System users → Add: name 'tracker-bot', role Admin."
step "Select it → Assign assets: Apps → your app (full control);"
step "   WhatsApp accounts → the test account (full control)."
step "Generate new token → choose your app → Expiration: Never →"
step "   permissions ${BOLD}whatsapp_business_messaging${RESET} + ${BOLD}whatsapp_business_management${RESET} → Generate, copy."
while :; do
  ask_secret WHATSAPP_ACCESS_TOKEN "Paste the system user token:"
  resp=$(graph GET "$WHATSAPP_PHONE_NUMBER_ID?fields=display_phone_number" || true)
  if [[ "$resp" == *display_phone_number* ]]; then
    printf '  %s✓ token works for test number %s%s\n' "$GREEN" "$(sed -E 's/.*"display_phone_number":"([^"]*)".*/\1/' <<<"$resp")" "$RESET"
    break
  fi
  warn "Meta rejected it: $(sed -E 's/.*"message":"([^"]*)".*/\1/' <<<"$resp" | cut -c1-160)"
  note "Check the assets are assigned and both permissions were ticked, then paste again."
done
WHATSAPP_VERIFY_TOKEN=$(openssl rand -hex 24)
printf '  %s✓ generated%s a random webhook verify token (kept in memory)\n' "$GREEN" "$RESET"
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Vercel environment variables"
say "Add each one as a Production variable. The wizard copies each value for you."
open_url "$VERCEL_ENV_URL"
note "For each: Add New → Key as shown → paste value (⌘V) → Environments: Production only"
note "→ mark Sensitive → Save. Then come back here and press Enter."
for name in GITHUB_TOKEN WHATSAPP_APP_SECRET WHATSAPP_ACCESS_TOKEN WHATSAPP_VERIFY_TOKEN WHATSAPP_PHONE_NUMBER_ID WHATSAPP_ALLOWED_FROM; do
  printf '\n'
  to_clipboard "$name" "${!name}"
  pause "Added ${BOLD}$name${RESET}${DIM}? Press Enter for the next one"
done
clear_clipboard

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Redeploy so the function sees the variables"
say "Env vars only apply to new deployments."
open_url "$VERCEL_DEPLOYS_URL"
step "Top Production deployment → ⋯ menu → Redeploy → Redeploy."
pause "Press Enter once it's redeploying; I'll watch for it to come up"
challenge="ok-$RANDOM"
for _ in $(seq 1 36); do
  got=$(curl -s --get "$WEBHOOK" --data-urlencode "hub.mode=subscribe" \
    --data-urlencode "hub.verify_token=$WHATSAPP_VERIFY_TOKEN" --data-urlencode "hub.challenge=$challenge" || true)
  [[ "$got" == "$challenge" ]] && break
  printf '  %s…waiting for the new deployment%s\r' "$DIM" "$RESET"; sleep 5
done
printf '\n'
if [[ "$got" == "$challenge" ]]; then
  printf '  %s✓ webhook answers the handshake with the new verify token%s\n' "$GREEN" "$RESET"
else
  warn "The webhook still rejects the verify token after 3 minutes."
  note "Check WHATSAPP_VERIFY_TOKEN is set for Production and the redeploy finished, then re-run."
  SKIPPED+=("Webhook handshake didn't pass; redeploy and check WHATSAPP_VERIFY_TOKEN")
fi
pause

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Point Meta's webhook at the site"
step "App dashboard → WhatsApp → Configuration (or Use cases → Customize → Configuration)."
step "Callback URL: ${BOLD}$WEBHOOK${RESET}"
to_clipboard "verify token" "$WHATSAPP_VERIFY_TOKEN"
step "Verify token: paste (⌘V) → Verify and save."
step "Webhook fields → Manage → subscribe to ${BOLD}messages${RESET}."
pause "Press Enter once it's saved and subscribed"
clear_clipboard
say "Making sure the app is subscribed to your WhatsApp account's events:"
resp=$(graph POST "$WABA_ID/subscribed_apps" || true)
if [[ "$resp" == *'"success":true'* ]]; then
  printf '  %s✓ app subscribed to WABA %s%s\n' "$GREEN" "$WABA_ID" "$RESET"
else
  warn "Subscribing failed: $(cut -c1-160 <<<"$resp")"
  SKIPPED+=("Subscribe the app to the WABA (POST /$WABA_ID/subscribed_apps)")
fi
pause

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Say hello"
step "On your phone, open WhatsApp and message the ${BOLD}test number${RESET}: today"
say "You should get today's checklist back within a few seconds."
note "Then log for real, e.g.  llm 50 ch1   or   lc 35   (send 'help' for the full syntax)."
if ! confirm "Did the bot reply?"; then
  note "Look at Vercel → Logs for /api/whatsapp:"
  note "  • 'Bad signature' (401): the app secret in Vercel doesn't match Meta's."
  note "  • 'Ignoring message from unlisted number': WHATSAPP_ALLOWED_FROM differs from your number."
  note "  • No request at all: webhook field 'messages' isn't subscribed."
  open_url "https://vercel.com/vikrams-projects-77a25b04/vrblog/logs"
  SKIPPED+=("End-to-end test message (see notes above)")
fi

finish
